Arriving.Z:
if (Scan.Depths == 1)
    Scan.EndImmediately();
else
    approachSpeed := 2*Scan.Size.Z/(Scan.Depths*Scan.PixelTime)*0.4096;

if (expectedZ == 0.0) {
    expectedZ := Scan.Size.Z + AveragedZ;
    offsetZ := Scan.Size.Z + AveragedZ;
    offsetZReverse := AveragedZ;
}
if (Scan.Time < 20)
    Scan.Arriving();
return [expectedZ];

MovingForward.Z:
expectedZ := UnaveragedZ + direction * approachSpeed;
if (direction == -1){


    if (abs(AveragedMechanical[1]) < RegulatorZ.RelativeSetpoint * RegulatorZ.MaximalPossibleSetpoint){
        offsetZReverse := UnaveragedZ;
        direction := 1.0;
        pixelReverse := PixelDepth;
        return []; 
    }

}

return [expectedZ];

MovingForward.RowColumnDepth:
if (direction == -1) {

    if (expectedZ <= offsetZ - 2.0*Scan.Size.Z * (PixelDepth+1)/Scan.Depths) {
    //    var depth := PixelDepth+1;
    //    if (depth >= Scan.Depths)
    //        Scan.End();
        return [PixelRow,PixelColumn,PixelDepth+1];
    }
}
else {
    if (expectedZ >= offsetZReverse + 2.0* Scan.Size.Z * (PixelDepth-pixelReverse+1)/Scan.Depths) {
        var depth := PixelDepth+1;
        if ((depth >= Scan.Depths) or (Scan.MaximumZ <= AveragedZ+0.05))
            Scan.End();
        return [PixelRow,PixelColumn,PixelDepth+1];
    }
}
return [PixelRow,PixelColumn,PixelDepth];
